use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},collections::BTreeMap,process::{Command,Stdio},io::Read};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn walk(p:&Path,out:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();let p=e.path();if e.file_type().unwrap().is_dir(){walk(&p,out)}else if e.file_type().unwrap().is_file(){out.push(p)}}}
fn main(){let r=Path::new("/tmp/zopro-stage-costs");let dest=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-26-stage-costs/artifacts");fs::create_dir_all(dest).unwrap();let a=read(r.join("analysis.json"));assert_eq!(a["sdk_requests"],376);assert_eq!(a["distinct_gnark_exports"],22);assert_eq!(a["timing_qualified"],false);
 for pins in ["source-pins.json","preflight-pins.json","performance-pins.json"]{for(p,h)in read(r.join(pins)).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap(),"pin {p}");}}
 let manifest=read("/tmp/zopro-grouping-module/production-source-manifest.json");let edits=read(r.join("edits.json"));let mut changed=Vec::new();for(rel,h)in manifest["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(rel)),h.as_str().unwrap());let p=r.join("candidate").join(rel);if hash(&p)!=h.as_str().unwrap(){changed.push(rel.clone());let mut s=fs::read_to_string(p).unwrap();for e in edits.as_array().unwrap().iter().rev().filter(|e|e["path"]==*rel){let new=e["new"].as_str().unwrap();assert_eq!(s.matches(new).count(),1);s=s.replacen(new,e["old"].as_str().unwrap(),1);}assert_eq!(format!("{:x}",Sha256::digest(s.as_bytes())),h.as_str().unwrap());}}
 assert_eq!(changed.len(),6);assert_eq!(hash("/tmp/zopro-grouping-module/native/candidate-sdk"),"03e1260e89068c2bec37a2471c34e93628a9f081903e1b7eee9cab9c306aaf3d");let inv=read(r.join("proof-inventory.json"));assert_eq!(inv.as_object().unwrap().len(),44);for(p,h)in inv.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}
 let close=json!({"status":"closed verified diagnostic; full timing calibration failed","sdk_requests":376,"distinct_gnark_exports":22,"proof_public_members":44,"timing_qualified":false,"trace_snapshots":104,"recorder_bytes":32768,"native_core_tests":113,"raw_tests":2,"cubic_tests":6,"analysis_tests":2,"accepted_sources_and_SDK_unchanged":true,"whole_originals_recovered":170,"changed_existing_diagnostic_files":changed,"new_cloud_resources":false,"adopted":false,"goal_achieved":false,"next_prior_proofs":5238,"no_successful_capture_repeated":true});fs::write(r.join("closeout.json"),serde_json::to_vec_pretty(&close).unwrap()).unwrap();
 let mut files=Vec::new();for d in ["native","preflight","performance","proofs","initial-schema-failure","originals"]{walk(&r.join(d),&mut files);}for e in fs::read_dir(r).unwrap(){let e=e.unwrap();if e.file_type().unwrap().is_file(){files.push(e.path());}}
 for p in changed{files.push(r.join("candidate").join(p));}for p in ["crates/zopro-core/src/stage_costs.rs","crates/zopro-bench/examples/cpu-sdk.rs","crates/zopro-bench/examples/support/perf.rs"]{files.push(r.join("candidate").join(p));}files.sort();files.dedup();let mut index=BTreeMap::new();let mut compressed=BTreeMap::new();
 for p in files{let rel=p.strip_prefix(r).unwrap();let ext=p.extension().and_then(|x|x.to_str()).unwrap_or("");if !matches!(ext,"rs"|"json"|"md"|"log"|"txt"|"proof"|"public"){continue;}let target=dest.join(rel);fs::create_dir_all(target.parent().unwrap()).unwrap();if p.file_name().unwrap()=="stages.json"{let gz=PathBuf::from(format!("{}.gz",target.display()));let f=fs::File::create(&gz).unwrap();assert!(Command::new("gzip").args(["-n","-c"]).arg(&p).stdout(Stdio::from(f)).status().unwrap().success());let decoded=Command::new("gzip").arg("-dc").arg(&gz).output().unwrap();assert!(decoded.status.success());assert_eq!(format!("{:x}",Sha256::digest(&decoded.stdout)),hash(&p));let key=gz.strip_prefix(dest).unwrap().display().to_string();index.insert(key.clone(),hash(&gz));compressed.insert(key,json!({"uncompressed_sha256":hash(&p),"uncompressed_bytes":fs::metadata(p).unwrap().len()}));}else{fs::copy(&p,&target).unwrap();index.insert(rel.display().to_string(),hash(target));}}
 fs::copy("/tmp/zopro-grouping-module/production-source-manifest.json",dest.join("accepted-source-manifest.json")).unwrap();index.insert("accepted-source-manifest.json".into(),hash(dest.join("accepted-source-manifest.json")));for(p,h)in &index{assert_eq!(hash(dest.join(p)),*h);}fs::write(dest.join("artifact-index.json"),serde_json::to_vec_pretty(&json!({"sha256":index,"compressed_json":compressed,"binaries_local_only":true})).unwrap()).unwrap();println!("Closed376SDK/22Gnark; {} archive hashes, {} compressed captures",index.len(),compressed.len());}
